UPDATE `emailtemplates` SET `TemplateText`='<html><head><title>APPLICANT DENIED APPLICATION</title></head> <body> <table width="100%" align="center" cellpadding="0" cellspacing="0" border="0" valign="top" bgcolor="#FFFFFF"> <tbody> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:14px 24px;border-bottom:3px solid #0A78D1;font-family:sans-serif;font-weight:400;"> <img src="https://i.imgur.com/YWp6idv.png" alt="logo" style="display:inline-block;float:left;vertical-align:middle;"/> </td></tr><tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:25px 23px 0 23px;font-family:sans-serif;font-weight:400;"> <span style="font-family:sans-serif;font-size:12px;font-weight:400;line-height:14px;color:#000000;display:inline-block;">Hi </span> <span style="font-family:sans-serif;font-size:12px;font-weight:700;line-height:14px;color:#000000;display:inline-block;">%FirstName% %LastName%,</span> </td></tr><tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:35px 23px 0 23px;font-family:sans-serif;font-weight:300;"> <span style="font-family:sans-serif;font-size:12px;font-weight:400;line-height:0px;color:#000000;display:inline-block;">We regret to inform you that your application number: %ApplicationId%, created on %StartDate% got denied.</span> </td></tr><tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:10px 23px 0 23px;font-family:sans-serif;font-weight:300;"> <span style="font-family:sans-serif;font-size:12px;font-weight:400;line-height:12px;color:#000000;display:inline-block;">We will explain the reasons for this decision in a letter you will receive within 7-10 days.</span> </td></tr><tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:35px 23px 0 23px;font-family:sans-serif;font-weight:300;"> <span style="font-family:sans-serif;font-size:12px;font-weight:400;line-height:14px;color:#000000;display:inline-block;">Sincerely, </span> </td></tr><tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:0px 23px 27px 23px;font-family:sans-serif;font-weight:300;border-bottom:1px solid #0A78D1"> <span style="font-family:sans-serif;font-size:12px;font-weight:700;line-height:14px;color:#000000;display:inline-block;">Temenos Digital Bank</span> </td></tr><tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:17px 23px 0px 23px;font-family:sans-serif;font-weight:300;"> <span style="font-family:sans-serif;font-size:11px;font-weight:400;line-height:13px;color:#000000;display:inline-block;">This is a system generated mail. Please do not reply to this e-mail address.</span> </td></tr><tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:7px 23px 0px 23px;font-family:sans-serif;font-weight:300;"> <span style="font-family:sans-serif;font-size:12px;font-weight:700;line-height:14px;color:#000000;display:inline-block;">Have any questions?</span> </td></tr><tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:7px 23px 0px 23px;font-family:sans-serif;font-weight:300;"> <div style="width:100%;display:inline-block;padding:18px 11px;vertical-align:middle;text-align:left;border-radius:3px;border:1px solid #E6E6E6;background-color:#FFFFFF"> <span style="font-family:sans-serif;font-size:12px;font-weight:400;line-height:14px;color:#000000;display:inline-block;">We can help, call us at</span> <span style="font-family:sans-serif;font-size:12px;font-weight:700;line-height:14px;color:#000000;display:inline-block;">&nbsp;1800-412-5434&nbsp;</span> <span style="font-family:sans-serif;font-size:12px;font-weight:400;line-height:14px;color:#000000;display:inline-block;">for assistance.</span> </div></td></tr><tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:17px 23px 0px 23px;font-family:sans-serif;font-weight:300;"> <span style="font-family:sans-serif;font-size:10px;font-weight:400;line-height:12px;color:#000000;display:inline-block;">CONFIDENTIALITY INFORMATION AND DISCLAIMER</span